fn main(){let a=std::env::args().collect::<Vec<_>>();let v:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[1]).unwrap()).unwrap();let p=v["points"].as_array().unwrap().iter().map(|p|glam::DVec2::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap())).collect::<Vec<_>>();let o=ingetrazo_gui::composer_cad::convex_bevel_outline(&p,v["radius"].as_f64().unwrap()).unwrap();let out=o.into_iter().map(|c|c.into_iter().map(|p|p.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>();std::fs::write(&a[2],serde_json::to_vec(&out).unwrap()).unwrap();}
